const raw = $('Webhook').item.json || {};
const wh = (raw.body && typeof raw.body === 'object') ? raw.body : raw;
const url = wh.url || 'Sin URL';
const instagram = wh.instagram || 'Sin Instagram';
const rubro = wh.rubro || 'No especificado';
const email = wh.email || '';

const siteRaw = $('Fetch Website').item.json;
const rawHtml = (siteRaw.data || siteRaw.body || '').toString();
const noTags = rawHtml.split('<').map(function(p){ return p.split('>').pop(); }).join(' ');
const cleanText = noTags.split(' ').filter(function(w){ return w.length > 0; }).join(' ').substring(0, 2000);

const ps = $input.item.json;
let perf = 0, acc = 0, seo = 0, fcp = 'N/D', lcp = 'N/D', cls = 'N/D';
try {
  const cats = ((ps.lighthouseResult || {}).categories) || {};
  perf = Math.round(((cats.performance || {}).score || 0) * 100);
  acc  = Math.round(((cats.accessibility || {}).score || 0) * 100);
  seo  = Math.round(((cats.seo || {}).score || 0) * 100);
  const aud = (ps.lighthouseResult || {}).audits || {};
  fcp = (aud['first-contentful-paint'] || {}).displayValue || 'N/D';
  lcp = (aud['largest-contentful-paint'] || {}).displayValue || 'N/D';
  cls = (aud['cumulative-layout-shift'] || {}).displayValue || 'N/D';
} catch(e) {}

const prompt = [
  'Analiza este negocio. Devuelve SOLO JSON valido sin markdown ni bloques de codigo.',
  'NEGOCIO: URL=' + url + ' | Instagram=@' + instagram + ' | Rubro=' + rubro,
  'PAGESPEED: Performance=' + perf + ' | SEO=' + seo + ' | Accesibilidad=' + acc,
  'FCP=' + fcp + ' LCP=' + lcp + ' CLS=' + cls,
  'CONTENIDO WEB: ' + cleanText,
  'ESTRUCTURA REQUERIDA (completa con analisis reales en espanol):',
  '{ score_general:0-100, resumen_ejecutivo:string, marketing:{score,presencia_digital,branding,redes_sociales,fortalezas:[3],mejoras:[3]}, seo:{score,tecnico,velocidad,contenido,problemas:[3],acciones:[5]}, competencia:{score,panorama,posicionamiento,ventajas:[3],desventajas:[2],diferenciacion}, crecimiento:{oportunidades:[5],quick_wins:[3],plan_30d:[3],plan_60d:[3],plan_90d:[3],kpis:[4]} }'
].join('\n');

const apiBody = JSON.stringify({
  model: 'llama-3.3-70b-versatile',
  messages: [
    { role: 'system', content: 'Eres un consultor de negocios digitales experto. Responde siempre en espanol. Devuelve SOLO JSON valido. Nunca uses markdown, nunca uses bloques de codigo.' },
    { role: 'user', content: prompt }
  ],
  max_tokens: 4000,
  temperature: 0.7
});

return [{json: {apiBody, url, instagram, rubro, email, pagespeed: {perf, acc, seo, fcp, lcp, cls}}}];
